const Data={
 P:MockProvider,
 all(){return this.P.universe.map(u=>({sym:u[0],name:u[1],type:u[2],sector:u[3],px:u[4],cap:u[5],pe:u[6],beta:u[7],ctry:u[8],g:Math.round((hash(u[0])%38)+(u[7]>1.5?8:0)),de:+((hash(u[0]+'d')%20)/10).toFixed(1)}))},
 get(s){return this.all().find(a=>a.sym===s)},
 hist(s,n=1260){const a=this.get(s),r=rng(hash(s)),v=a.beta*.011+.004;let p=a.px*.62,o=[];for(let i=0;i<n;i++){p*=1+(r()-.47)*v*2;o.push(p)}const k=a.px/o[n-1];return o.map(x=>x*k)},
 chg(s){const h=this.hist(s,30),d=(h[29]/h[28]-1)*100;return +d.toFixed(2)},
 search(q){q=q.toLowerCase().trim();if(!q)return{};const sc=a=>{const t=(a.sym+' '+a.name+' '+a.sector).toLowerCase();if(t.includes(q))return 2+(a.sym.toLowerCase()==q?3:0)+(a.sym.toLowerCase().startsWith(q)?1:0);let i=0;for(const c of t)if(c==q[i])i++;return i==q.length&&q.length>2?1:0};
  const out={},grp={Stock:'Securities',ADR:'Securities',ETF:'Funds',Index:'Indices',Commodity:'Commodities',Currency:'Currencies',Crypto:'Crypto',Bond:'Economic data'};
  this.all().map(a=>[sc(a),a]).filter(x=>x[0]).sort((x,y)=>y[0]-x[0]).slice(0,12).forEach(([,a])=>(out[grp[a.type]]??=[]).push({t:a.sym+'  '+a.name,h:'#/asset/'+encodeURIComponent(a.sym)}));
  for(const k in this.P.concepts)if(k.includes(q)||q.includes(k)){out['Related assets']=this.P.concepts[k].filter(s=>this.get(s)).map(s=>({t:s+'  '+this.get(s).name,h:'#/asset/'+encodeURIComponent(s)}));out['Education']=[{t:'Lesson: how '+k+' moves markets',h:'#/learn'}];out['News']=[{t:'News and events tagged “'+k+'”',h:'#/news'}];out['Research']=[{t:'Market reaction study: '+k,h:'#/asset/NVDA'}]}
  if(out.Securities||out.Funds)out['Education']=[{t:'Lesson: reading a company profile',h:'#/learn'}];
  return out}
};
