const $=s=>document.querySelector(s),fmt=(n,d=2)=>n.toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d}),pc=c=>`<span class="${c>=0?'up':'dn'}">${c>=0?'+':''}${fmt(c)}%</span>`;
