function svg(lines,w=860,h=300,log){const pad=6;let all=lines.flatMap(l=>l.d.filter(x=>x!=null)),f=x=>log?Math.log(x):x,mn=f(Math.min(...all)),mx=f(Math.max(...all));
 return `<svg viewBox="0 0 ${w} ${h}" style="width:100%;height:auto;display:block">`+[.25,.5,.75].map(t=>`<line x1="0" x2="${w}" y1="${h*t}" y2="${h*t}" stroke="var(--ln)"/>`).join('')+lines.map(l=>{const n=l.d.length;let p='';l.d.forEach((v,i)=>{if(v==null)return;p+=(p?'L':'M')+(i/(n-1)*w).toFixed(1)+' '+(pad+(1-(f(v)-mn)/(mx-mn||1))*(h-2*pad)).toFixed(1)});return `<path d="${p}" fill="none" stroke="${l.c}" stroke-width="${l.w||1.5}" ${l.dash?'stroke-dasharray="4 3"':''}/>`}).join('')+'</svg>'}
