PAGES.home=()=>{$('#m').innerHTML=`<div class="hero"><canvas id="cv"></canvas><div id="tip"></div><div class="t"><h1>QUANTERA</h1><p>Understand the world’s financial system.<br>Markets. Research. Intelligence. Education. One system.</p><div><a class="btn p" href="#/markets">Explore Markets</a><a class="btn" href="#/terminal">Enter Terminal</a></div></div></div>
<section style="padding:80px 0 0"><h2 style="font-size:clamp(26px,4vw,44px);max-width:760px;font-weight:500">Other sites tell you what happened. Quantera shows why, how the market reacted, and what else moved.</h2>
<div class="g g3" style="margin-top:36px">${[['What happened','Quotes, charts, filings and news for any security the data provider carries.'],['Why and how it reacted','Market Reaction Intelligence compares speed, magnitude and recovery across assets for the same event.'],['How confident we are','Every output states its source, sample size and method, split into data, analysis and interpretation.']].map(x=>`<div class="pan"><h3>${x[0]}</h3><span class="mu">${x[1]}</span></div>`).join('')}</div>
<p class="mu" style="margin-top:28px">Prototype build. All prices, fundamentals and statistics are mock data from a replaceable provider layer. No live market access is claimed.</p></section>`;
 const cv=$('#cv'),x=cv.getContext('2d'),tip=$('#tip'),dpr=devicePixelRatio||1,mob=innerWidth<800,N=mob?450:1400,named=Data.all(),r=rng(5);
 const nodes=Array.from({length:N},(_,i)=>{const u=r()*2-1,t=r()*6.283,k=Math.sqrt(1-u*u)*(.55+r()*.45);return{x:k*Math.cos(t),y:u*.8,z:k*Math.sin(t),a:i<named.length?named[i]:null,c:i%7}});
 const links=[];for(let i=0;i<N*1.2;i++){const a=(r()*N)|0,b=(r()*N)|0;if(Math.hypot(nodes[a].x-nodes[b].x,nodes[a].y-nodes[b].y,nodes[a].z-nodes[b].z)<.45)links.push([a,b])}
 let W,H,mx=0,my=0,t=0,hv=-1,raf,P=[];const rs=()=>{W=cv.clientWidth;H=cv.clientHeight;cv.width=W*dpr;cv.height=H*dpr;x.setTransform(dpr,0,0,dpr,0,0)};rs();addEventListener('resize',rs);
 cv.onmousemove=e=>{const b=cv.getBoundingClientRect();mx=(e.clientX-b.left)/W-.5;my=(e.clientY-b.top)/H-.5;hv=-1;let best=14;P.forEach((p,i)=>{if(!nodes[i].a)return;const d=Math.hypot(p[0]-(e.clientX-b.left),p[1]-(e.clientY-b.top));if(d<best){best=d;hv=i}});
  if(hv>=0){const a=nodes[hv].a;tip.style.display='block';tip.style.left=e.clientX-b.left+14+'px';tip.style.top=e.clientY-b.top+'px';tip.innerHTML=`<b>${a.sym}</b> ${a.name}<br><span class="mu">${a.type} · ${a.sector}</span>`}else tip.style.display='none'};
 cv.onclick=()=>{if(hv>=0)go('#/asset/'+encodeURIComponent(nodes[hv].a.sym))};
 const col=['#8fb4e8','#5fb89a','#c9b27a','#8b93a3','#a9b8d6','#7aa6a0','#b79a8e'];
 const draw=()=>{t+=.0016;x.clearRect(0,0,W,H);const ry=t+mx*.9,rx=my*.5,cy=Math.cos(ry),sy=Math.sin(ry),cx=Math.cos(rx),sx=Math.sin(rx),S=Math.min(W,H)*.52;
  P=nodes.map(n=>{let X=n.x*cy-n.z*sy,Z=n.x*sy+n.z*cy,Y=n.y*cx-Z*sx;Z=n.y*sx+Z*cx;const k=1/(1.9-Z*.5);return[W*.62+X*S*k,H*.46+Y*S*k,Z,k]});
  x.strokeStyle='rgba(143,180,232,.07)';x.beginPath();links.forEach(([a,b])=>{x.moveTo(P[a][0],P[a][1]);x.lineTo(P[b][0],P[b][1])});x.stroke();
  P.forEach((p,i)=>{const n=nodes[i];x.globalAlpha=.25+.6*(p[2]+1)/2;x.fillStyle=i==hv?'#fff':col[n.c];x.beginPath();x.arc(p[0],p[1],(n.a?2.6:1.2)*p[3]*1.5+(i==hv?2:0),0,6.283);x.fill()});x.globalAlpha=1;raf=requestAnimationFrame(draw)};draw();
 stopHero=()=>{cancelAnimationFrame(raf);removeEventListener('resize',rs)}};
