 const P=(i,j)=>{const X=(i/n-.5)*2,Z=(j/m-.5)*2,t=(V[i][j]-mn)/(mx-mn||1),Y=.7-t*1.4,x1=X*c+Z*s,z1=-X*s+Z*c;return{x:350+x1*sc,y:175+(Y*cp-z1*sp)*sc,z:Y*sp+z1*cp,t}},q=[];
 for(let i=0;i<n;i++)for(let j=0;j<m;j++){const p=[P(i,j),P(i+1,j),P(i+1,j+1),P(i,j+1)];q.push({p,z:p.reduce((u,w)=>u+w.z,0)/4,t:p.reduce((u,w)=>u+w.t,0)/4})}
