 $('#m').innerHTML=`<h2 style="font-size:36px">Valuation (DCF)</h2><p class="mu">Estimate what a company is worth from its cash flows, then stress-test the assumptions. Pick a company to load starting inputs from the mock data.</p><div class="g sp"><div class="pan"><label>Load company</label>${sel_('vc',['Custom',...ST.map(a=>a.sym)],'Custom')}${[['f','Free cash flow ($B)',1,200,1],['g','Growth, 10 years (%)',0,35,1],['d','Discount rate (%)',6,14,.5],['t','Terminal growth (%)',0,4,.5],['sh','Shares (B)',.1,30,.1],['px','Current price ($)',5,1000,1]].map(a=>`<label>${a[1]} <b id="v${a[0]}"></b></label><input type=range min=${a[2]} max=${a[3]} step=${a[4]} data-k="${a[0]}">`).join('')}</div><div class="pan" id="vo"></div></div>`;
