PAGES.calendar=()=>{let f='All';const d=n=>{const t=new Date(2026,9,6+n);return t.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})},E=[[1,'Economic','Inflation report (CPI)','Measures how fast prices are rising. Affects interest rate expectations.','High'],[2,'Earnings','NVIDIA earnings','Shows if AI chip demand is holding up.','High'],[3,'Dividends','Apple dividend payment','Cash paid to shareholders.','Low'],[4,'Economic','Central bank meeting','Decides interest rates, which move bonds, stocks and currencies.','High'],[6,'Earnings','JPMorgan earnings','A read on the health of lending and the economy.','Medium'],[8,'IPO','Sample IPO pricing','A company sells shares to the public for the first time.','Medium'],[9,'Economic','Jobs report','Shows how many people are working. Strong jobs can mean higher rates.','High']],p=()=>{$('#cf').innerHTML=['All','Earnings','Economic','Dividends','IPO'].map(k=>`<button class="chip ${k==f?'on':''}" onclick="CF_('${k}')">${k}</button>`).join('');$('#cl').innerHTML=E.filter(e=>f=='All'||e[1]==f).map(e=>`<tr><td>${d(e[0])}</td><td><span class="tag">${e[1]}</span></td><td><b>${e[2]}</b><div class="mu">${e[3]}</div></td><td><span class="pill ${e[4]=='High'?'d':'u'}">${e[4]} impact</span></td></tr>`).join('')};window.CF_=k=>{f=k;p()};$('#m').innerHTML='<div class="pan ov"><div class="pre" id="cf"></div><table><tr><th>Date</th><th>Type</th><th>Event</th><th>Importance</th></tr><tbody id="cl"></tbody></table></div><div class="pv">Sample schedule for the prototype. Real dates would come from the data provider.</div>';p()};
