cashflow:{s:[['rev','Revenue ($M)',100,5000,50,1000],['ocf','Operating cash flow ($M)',-100,1500,10,200],['cx','Capital spending ($M)',0,1000,10,120],['mc','Market value ($M)',100,20000,100,3000]],f:S=>{const f=S.ocf-S.cx;return `<div class="big ${f>=0?'up':'dn'}">$${fmt(f,0)}M</div><span class="mu">free cash flow</span>`+KV('FCF margin',fmt(f/S.rev*100,1)+'%')+KV('FCF yield on market value',fmt(f/S.mc*100,1)+'%')}},
peg:{s:[['pe','P/E ratio',5,100,1,30],['g','Expected earnings growth (% a year)',1,60,1,20]],f:S=>{const p=S.pe/S.g;return `<div class="big">PEG ${fmt(p,2)}</div><p class="mu">${p<1?'Below 1: priced low for its growth.':p<2?'Around 1 to 2: priced roughly in line with growth.':'Above 2: expensive for its growth.'} Growth forecasts are uncertain, so treat this as a rough guide.</p>`}},
capm:{s:[['rf','Risk-free rate (%)',0,8,.25,4],['b','Beta',0,3,.1,1.2],['m','Market risk premium (%)',2,12,.25,6]],f:S=>{const r=S.rf+S.b*S.m;return `<div class="big">${fmt(r,1)}%</div><span class="mu">return this stock should offer for its risk</span>`+svg([{d:Array.from({length:31},(_,i)=>S.rf+i/10*S.m),c:'var(--ac)',w:2}],700,140)+'<div class="mu">The line shows required return as beta rises from 0 to 3.</div>'}},
