const rt15=route;route=function(){rt15();const [,r='',a]=location.hash.split('/'),arg=decodeURIComponent(a||'');tape();
 const t=TTL[r]?TTL[r](arg):TT[r]&&TT[r][0];document.title=t?t+' · Quantera':'Quantera · Markets, research and investing education'};
